import React from 'react';
import { isElement } from 'react-is';

import { defaultYAxisConfig } from '../constants.js';
import { SparklineThresholdProps, Threshold } from '../slots/Threshold.js';
import { SparklineYAxisProps, YAxis } from '../slots/YAxis.js';

export interface SparklineConfig {
  thresholds: SparklineThresholdProps[];
  yAxis: SparklineYAxisProps;
}

export function iterateSlots(children: React.ReactNode): SparklineConfig {
  const thresholds: SparklineThresholdProps[] = [];
  let yAxis: SparklineYAxisProps = defaultYAxisConfig;

  React.Children.forEach(children, (child) => {
    if (isElement(child)) {
      if (child.type === Threshold) {
        const thresholdProps = child.props as SparklineThresholdProps;
        thresholds.push(thresholdProps);
      } else if (child.type === YAxis) {
        yAxis = {
          ...yAxis,
          ...(child.props as SparklineYAxisProps),
        };
      }
    }
  });

  return {
    thresholds,
    yAxis,
  };
}
